    "นายเกรียงไกรเป็นพนักงานราชการสังกัดกระทรวงมหาดไทย ตำแหน่งพนักงานขับรถยนต์ ได้รับการประเมินผลการปฏิบัติงานครั้งแรกของปีงบประมาณ 2566 ให้ขึ้นเงินเดือนเพียง 0.5 ขั้น เขาเห็นว่าผู้บังคับบัญชาไม่ปฏิบัติตามหลักเกณฑ์และวิธีปฏิบัติในระบบเปิดที่กระทรวงกำหนด จึงอุทธรณ์ผลการประเมินต่อผู้บังคับบัญชาระดับสูงขึ้นไป แต่ผลการพิจารณาอุทธรณ์ยังยืนตามเดิม เขาต้องการฟ้องคดีต่อศาลเพื่อเรียกร้องความเป็นธรรม",
