    "**หลักจับคู่ ม.9 ↔ ม.72:** ม.9(1) → ม.72(1) เพิกถอน/ห้าม · ม.9(2) → ม.72(2) สั่งให้ปฏิบัติหน้าที่ · ม.9(3),(4) → ม.72(3) ใช้เงิน/ส่งมอบ/กระทำ · ม.72(4) แสดงความเป็นอยู่ของสิทธิหน้าที่ (พิสูจน์สิทธิ)",
