   "title": "คำสั่งอธิการบดีปิดและรื้อโรงอาหารกลางเพื่อให้เอกชนสร้างใหม่ · นักศึกษาฟ้องเพิกถอน",
   "facts": [
    "อธิการบดีของมหาวิทยาลัยรัฐแห่งหนึ่งเห็นว่าโรงอาหารกลางของวิทยาเขตแห่งหนึ่งซึ่งก่อสร้างและใช้ประโยชน์มานาน มีสภาพไม่เหมาะสมกับจำนวนนักศึกษาที่เพิ่มขึ้น และมีพื้นที่ใช้สอยไม่เพียงพอ จึงเตรียมให้มีการก่อสร้างอาคารโรงอาหารกลางแห่งใหม่เป็นอาคารคอนกรีต 3 ชั้น ชั้นล่างเป็นที่จอดรถ ชั้นสองเป็นโรงอาหาร ชั้นสามเป็นร้านอาหารและศูนย์การสอนภาษาอังกฤษของสถาบันเอกชนภายนอก โดยหาผู้ดำเนินการก่อสร้างที่ออกค่าก่อสร้างเอง แลกกับสิทธิบริหารอาคาร 25 ปี เมื่อคัดเลือกผู้ดำเนินการได้แล้ว อธิการบดีสั่งให้ปิดโรงอาหารเดิม จัดเตรียมพื้นที่ขายอาหารชั่วคราว และเริ่มรื้อถอนอาคารเดิม",
    "นายกวินเป็นนักศึกษาคณะนิติศาสตร์และเป็นกรรมการสภานักศึกษา ไม่เห็นด้วยเพราะเห็นว่าค่าอาหารจะสูงขึ้นและมีทางเลือกน้อยลง จึงยื่นหนังสือคัดค้านต่ออธิการบดี อธิการบดีชี้แจงว่าเป็นไปเพื่อประโยชน์และคุณภาพชีวิตของนักศึกษาโดยรวม แต่นายกวินยังไม่เห็นด้วย จึงฟ้องต่อศาลปกครองกลางขอให้เพิกถอนคำสั่งอธิการบดีที่ให้ปิดโรงอาหารและเตรียมรื้อถอน โดยให้เหตุผลว่าเป็นคำสั่งทางปกครองที่กระทบสิทธิเสรีภาพของนักศึกษา สร้างภาระเกินสมควร และไม่เปิดโอกาสให้นักศึกษาที่ได้รับผลกระทบแสดงความเห็นหรือโต้แย้งก่อนตัดสินใจ"
   ],
