   "memo": [
    "**พ.ร.บ.วิธีปฏิบัติราชการทางปกครอง ม.5 (คำสั่งทางปกครอง):** การใช้อำนาจตามกฎหมายของเจ้าหน้าที่ที่มีผลเป็นการสร้างนิติสัมพันธ์ขึ้นระหว่างบุคคลในอันที่จะก่อ เปลี่ยนแปลง โอน สงวน ระงับ หรือมีผลกระทบต่อสถานภาพของสิทธิหรือหน้าที่ของบุคคล ไม่ว่าจะเป็นการถาวรหรือชั่วคราว เช่น การสั่งการ การอนุญาต การอนุมัติ การวินิจฉัยอุทธรณ์ การรับรอง การรับจดทะเบียน — แต่ไม่รวมการออกกฎ",
    "**ม.9 ว.1(1):** คดีที่หน่วยงานทางปกครองหรือเจ้าหน้าที่ของรัฐกระทำการโดยไม่ชอบด้วยกฎหมาย ไม่ว่าออกกฎ คำสั่ง หรือการกระทำอื่นใด เพราะ ไม่มีอำนาจ/นอกอำนาจ · ไม่ถูกต้องตามรูปแบบ ขั้นตอน วิธีการอันเป็นสาระสำคัญ · ไม่สุจริต · เลือกปฏิบัติที่ไม่เป็นธรรม · สร้างขั้นตอนโดยไม่จำเป็นหรือสร้างภาระเกินสมควร · ใช้ดุลพินิจโดยมิชอบ",
    "**ม.42 ว.1:** ผู้ใดได้รับความเดือดร้อนหรือเสียหาย หรืออาจจะเดือดร้อนหรือเสียหายโดยมิอาจหลีกเลี่ยงได้ อันเนื่องจากการกระทำหรือการงดเว้นการกระทำของหน่วยงานทางปกครองหรือเจ้าหน้าที่ของรัฐ หรือมีข้อโต้แย้งเกี่ยวกับสัญญาทางปกครอง หรือกรณีอื่นใดที่อยู่ในเขตอำนาจศาลปกครองตามมาตรา 9 และการแก้ไขหรือบรรเทาความเดือดร้อนหรือความเสียหายหรือยุติข้อโต้แย้งนั้นต้องมีคำบังคับตามมาตรา 72 — ผู้นั้นมีสิทธิฟ้องคดีต่อศาลปกครอง",
    "**ม.42 ว.2:** ถ้ามีกฎหมายกำหนดขั้นตอนหรือวิธีการแก้ไขความเดือดร้อนไว้โดยเฉพาะ จะฟ้องได้ต่อเมื่อดำเนินการตามขั้นตอนนั้นแล้ว และมีการสั่งการตามกฎหมายนั้น หรือมิได้สั่งการภายในเวลาอันสมควรหรือภายในเวลาที่กฎหมายกำหนด",
    "**พ.ร.บ.วิธีปฏิบัติราชการทางปกครอง ม.30 ว.1:** ถ้าคำสั่งทางปกครองอาจกระทบถึงสิทธิของคู่กรณี เจ้าหน้าที่ต้องให้คู่กรณีมีโอกาสทราบข้อเท็จจริงอย่างเพียงพอ และมีโอกาสโต้แย้งและแสดงพยานหลักฐานของตน",
    "**ม.72 ว.1 (คำบังคับ):** (1) เพิกถอนกฎหรือคำสั่ง หรือห้ามการกระทำ [คดี ม.9(1)] · (2) สั่งให้ปฏิบัติหน้าที่ภายในเวลาที่กำหนด [ม.9(2)] · (3) ให้ใช้เงิน ส่งมอบทรัพย์ กระทำหรืองดเว้นกระทำ [ละเมิด/ความรับผิดอื่น/สัญญา] · (4) ถือปฏิบัติต่อสิทธิหรือหน้าที่ของบุคคล = คำพิพากษาแสดงความเป็นอยู่ของสิทธิหรือหน้าที่ · (5) สั่งบุคคลกระทำหรือละเว้นกระทำเพื่อให้เป็นไปตามกฎหมาย",
    "**ม.66:** ศาลปกครองกำหนดมาตรการหรือวิธีการเพื่อบรรเทาทุกข์ให้คู่กรณีเป็นการชั่วคราวก่อนการพิพากษาได้ ไม่ว่าจะมีคำร้องหรือไม่ ตามระเบียบของที่ประชุมใหญ่ตุลาการในศาลปกครองสูงสุด"
   ],
   "kind": "โจทย์ความเห็นพนักงานคดี"
