     "เป็นคำสั่งทางปกครอง ตามมาตรา 5 พ.ร.บ.วิธีปฏิบัติราชการทางปกครองฯ เพราะเป็นการใช้อำนาจตามกฎหมาย (ข้อบังคับของมหาวิทยาลัยว่าด้วยกิจกรรมนักศึกษา) ของเจ้าหน้าที่ของรัฐ ซึ่งกระทบสถานภาพของสิทธิของนางสาวมณีโดยตรง คือสิทธิที่จะดำรงตำแหน่งที่ตนได้รับเลือก จึงฟ้องเพิกถอนได้ตามมาตรา 9 วรรคหนึ่ง (1)"
