     "รับฟังได้ การที่มหาวิทยาลัยแต่งตั้งนายขวัญ เท่ากับเป็นการปฏิเสธนางสาวมณีไปในตัว นางสาวมณีกับนายขวัญจึงเป็น “คู่กรณี” ตามมาตรา 5 พ.ร.บ.วิธีปฏิบัติราชการทางปกครองฯ ซึ่งหมายถึงผู้ยื่นคำขอหรือผู้คัดค้านคำขอ และผู้อยู่ในบังคับหรือจะอยู่ในบังคับของคำสั่ง คำสั่งปฏิเสธนี้กระทบสิทธิของนางสาวมณีโดยตรง อธิการบดีจึงต้องเปิดโอกาสให้เธอทราบข้อเท็จจริงและโต้แย้งแสดงพยานหลักฐานก่อนตามมาตรา 30 วรรคหนึ่ง เมื่อไม่เปิดโอกาส คำสั่งจึงออกโดยไม่ถูกต้องตามขั้นตอนอันเป็นสาระสำคัญ ไม่ชอบด้วยกฎหมาย และไม่เข้าข้อยกเว้นตามมาตรา 30 วรรคสอง (เช่น กรณีจำเป็นรีบด่วน หรือเป็นข้อเท็จจริงที่คู่กรณีให้ไว้เอง)"
