   "title": "ระเบียบกระทรวงมหาดไทยว่าด้วยคณะกรรมการชุมชนของเทศบาล — สมาคมฟ้องเพิกถอน",
   "facts": [
    "รัฐมนตรีว่าการกระทรวงมหาดไทยออกระเบียบกระทรวงมหาดไทยว่าด้วยคณะกรรมการชุมชนของเทศบาล พ.ศ. 2564 ลงนามประกาศระเบียบเมื่อวันที่ 10 กุมภาพันธ์ 2564 และนำไปประกาศในราชกิจจานุเบกษาเมื่อวันที่ 25 กุมภาพันธ์ 2564",
    "สมาคมพัฒนาประชากรและชุมชน ซึ่งเป็นองค์กรเอกชนที่มีวัตถุประสงค์ส่งเสริมและสนับสนุนให้ประชาชนในชุมชนมีบทบาทและส่วนร่วมในการพัฒนาชุมชนของตนเอง เห็นว่าระเบียบดังกล่าวกำหนดหลักเกณฑ์การมีส่วนร่วมของประชาชนในชุมชนไม่เหมาะสมและไม่เป็นไปตามเจตนารมณ์เรื่องสิทธิในชุมชนที่รัฐธรรมนูญ พ.ศ. 2560 รับรองไว้ในมาตรา 43 จึงประสงค์ฟ้องต่อศาลปกครองในวันที่ 24 พฤษภาคม 2564 ขอให้เพิกถอนระเบียบดังกล่าว กระทรวงมหาดไทยโต้แย้งว่าสมาคมเป็นองค์กรเอกชนไม่ใช่บุคคลในชุมชนแห่งใดแห่งหนึ่ง ไม่ได้ถูกโต้แย้งสิทธิหรือถูกกระทบสิทธิ จึงไม่มีอำนาจฟ้อง และเวลาก็ล่วงเลยจนหมดสิทธิฟ้องแล้ว"
   ],
   "asks": [
    "จงวินิจฉัย (1) คดีอยู่ในอำนาจศาลปกครองหรือไม่ (2) คดีอยู่ในอำนาจศาลปกครองชั้นใด (3) สมาคมเป็นผู้มีสิทธิฟ้องคดีหรือไม่ (4) ต้องอุทธรณ์หรือโต้แย้งระเบียบต่อรัฐมนตรีหรือองค์กรอื่นในฝ่ายบริหารก่อนฟ้องหรือไม่ (5) หากฟ้องวันที่ 24 พฤษภาคม 2564 ยังอยู่ในระยะเวลาที่ฟ้องได้หรือไม่ เพราะเหตุใด"
   ],
