/* ================================================================
   War Mode (constproc.html) — คลังข้อสอบเก่า วิ.ปกครอง / วิ.รัฐธรรมนูญ
   ข้อมูลอยู่ใน WAR_DATA (ด้านบนของไฟล์นี้) · ตัวแสดงผลอยู่ด้านล่าง
   ไม่มีชื่ออาจารย์/มหาวิทยาลัย และชื่อตัวละครในโจทย์ถูกเปลี่ยนแล้ว
   ================================================================ */
(function(){
  function esc(s){ return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;'); }
  function inl(s){ return esc(s).replace(/\*\*([\s\S]+?)\*\*/g,'<strong>$1</strong>'); }

  // ตัดชื่อสถาบัน/หน่วยภายในมหาวิทยาลัยออกจากบล็อกโจทย์ที่ยกมาจากคาบเรียน (ไม่แก้ต้นฉบับในหน้าบรรยาย)
  // WAR_SCRUB = [[regex-string, replacement], ...] (เก็บเป็น \\uXXXX ในไฟล์ข้อมูล)
  function scrub(html){
    return WAR_SCRUB.reduce(function(s, r){ return s.replace(new RegExp(r[0],'g'), r[1]); }, html);
  }

  function ansHtml(blocks){
    return blocks.map(b=>{
      const t=b[0], v=b[1];
      if(t==='h')  return '<div class="ans-issue">'+inl(v)+'</div>';
      if(t==='p')  return '<div>'+inl(v)+'</div>';
      if(t==='v')  return '<div><span class="verdict">'+inl(v)+'</span></div>';
      if(t==='ul') return '<ul class="war-ul">'+v.map(x=>'<li>'+inl(x)+'</li>').join('')+'</ul>';
      if(t==='off') return '<div class="war-off"><span class="war-off-tag">อนึ่ง (นอกประเด็นเล็กน้อย — แสดงความรู้ประกอบ)</span>'+inl(v)+'</div>';
      if(t==='note') return '<div class="war-note">'+inl(v)+'</div>';
      return '';
    }).join('');
  }

  function questionHtml(q){
    const facts=(q.facts||[]).map(p=>'<p>'+inl(p)+'</p>').join('');
    const asks=(q.asks||[]).map(p=>'<p class="war-ask">'+inl(p)+'</p>').join('');
    const kind=q.kind==='problem'?'โจทย์ตุ๊กตา':'โจทย์อธิบาย/แสดงความเห็น';
    const src=(q.src||[]).join(' · ');
    const ans=(q.answer&&q.answer.length)
      ? '<details class="war-ans"><summary>👁 ดูธงคำตอบ</summary><div class="exam-answer"><div class="ans-title">'+(q.answerTitle||'ธงคำตอบ (ร่าง — ตรวจซ้ำกับตัวบทและเอกสารประกอบก่อนใช้จริง)')+'</div>'+ansHtml(q.answer)+'</div></details>'
      : '<div class="war-note">⏳ ธงคำตอบข้อนี้รอเพิ่มหลังอาจารย์บรรยาย</div>';
    return '<div class="war-q" id="wq-'+q.id+'">'
      + '<div class="war-q-head"><span class="war-q-id">'+q.id+'</span><span class="war-q-kind">'+kind+'</span></div>'
      + '<div class="war-q-title">'+inl(q.title)+'</div>'
      + '<div class="war-q-src">ออกสอบ: '+esc(src)+'</div>'
      + '<div class="war-q-body">'+facts+asks+'</div>'
      + ans + '</div>';
  }

  function panelHtml(part){
    const D=WAR_DATA, P=D.parts[part];
    const issues=D.issues.filter(i=>i.part===part);
    const qs=D.questions.filter(q=>q.part===part);
    let h=PRINT_BAR+'<div class="board-note war-intro"><div class="board-note-title">'+esc(P.title)+'</div>'+P.intro.map(x=>'<p>'+inl(x)+'</p>').join('')+'</div>';
    h+='<div class="war-map"><div class="war-map-title">แผนที่ประเด็น (กดเพื่อกระโดดไป)</div>'
      + issues.map(i=>'<a class="war-chip" href="#war-issue-'+i.n+'" onclick="warJump(event,'+i.n+')"><b>'+i.n+'</b> '+esc(i.short)+'<span class="war-chip-n">'+i.count+' โจทย์</span></a>').join('')+'</div>';
    issues.forEach(i=>{
      const iq=qs.filter(q=>q.issue===i.n);
      h+='<details class="war-issue" id="war-issue-'+i.n+'" open><summary><span class="war-issue-n">'+i.n+'</span><span class="war-issue-name">'+esc(i.name)+'</span><span class="war-issue-freq">'+esc(i.freq)+'</span></summary>'
        + '<div class="war-issue-body"><div class="war-keys"><div class="war-keys-title">หลักที่ต้องมี (ธงประเด็น)</div>'+i.keys.map(k=>'<div>'+inl(k)+'</div>').join('')+'</div>'
        + iq.map(questionHtml).join('') + '</div></details>';
    });
    if(part==='A') h+=lectureBankHtml();
    return h;
  }

  // กล่อง "มาตราที่ต้องท่อง" — คนละสีกับกล่องเฉลย (เขียว) และกล่อง "อนึ่ง" (ทอง) : ม่วง
  (function(){
    const st=document.createElement('style');
    st.textContent='.war-memo{margin-top:12px;padding:12px 14px;border:1px solid #7C5CC4;border-left:4px solid #7C5CC4;background:#EFEAFB;border-radius:8px;font-size:13px;line-height:1.85;color:var(--ink)}'
      +'.war-memo-title{font-weight:800;font-size:12.5px;color:#5B3FA6;margin-bottom:6px;letter-spacing:.2px}'
      +'.war-memo ul{margin:0;padding-left:18px}.war-memo li{margin:0 0 6px}'
      +':root[data-theme="dark"] .war-memo,:root[data-theme="horror"] .war-memo{background:#2A2440;border-color:#A78BFA;color:var(--ink)}'
      +':root[data-theme="dark"] .war-memo-title,:root[data-theme="horror"] .war-memo-title{color:#C4B5FD}';
    document.head.appendChild(st);
  })();

  // ---------- พิมพ์ / บันทึก PDF ----------
  // เว้นขอบซ้ายกว้างเผื่อสันเย็บเล่ม (Chrome ไม่สลับขอบซ้าย-ขวาตามหน้าให้ จึงใช้ขอบซ้ายคงที่) · ขยายเฉลยทุกข้อก่อนพิมพ์อัตโนมัติ
  // กฎพิมพ์ทั้งหมดผูกกับ body.war-printing (ใส่เฉพาะตอนแท็บ War Mode เปิดอยู่) เพื่อไม่กระทบระบบพิมพ์เดิมของหน้า
  const PRINT_RULES=[
    ['.wrap','max-width:none !important;width:auto !important;margin:0 !important;padding:0 !important'],
    ['.mode-tabs,.war-print-bar,.war-map,.coffee-widget,footer,.war-lec-body>.war-note,.tts-bar,.page-head .crest','display:none !important'],
    ['.page-head','margin:0 0 8mm !important;padding:0 !important'],
    ['.page-head h1','font-size:18pt !important'],
    ['.mode-panel:not(.active),#panel-read,#printArea','display:none !important'],
    ['.war-q,.war-issue,.war-lec,.war-issue-body,.war-lec-body','border-radius:0 !important'],
    ['.war-issue,.war-lec','border:0 !important;background:transparent !important'],
    ['.war-issue-body,.war-lec-body','padding:0 !important'],
    ['.war-issue>summary,.war-lec>summary','padding-left:0 !important'],
    ['summary','list-style:none'],
    ['summary::-webkit-details-marker','display:none'],
    ['.war-ans>summary','display:none'],
    ['.war-q','break-inside:auto;page-break-inside:auto;padding:3mm 4mm;margin:5mm 0'],
    ['.war-q-head,.war-q-title,.ans-issue,.war-keys-title,.war-memo-title,.war-off-tag,.ans-title','break-after:avoid;page-break-after:avoid'],
    ['.war-off,.war-memo,.war-keys,.war-memo li,.exam-answer .verdict','break-inside:avoid;page-break-inside:avoid'],
    ['.war-q-body,.exam-answer,.war-memo,.war-off,.war-keys','font-size:10.5pt !important;line-height:1.7 !important'],
    ['.war-memo.war-memo','background:#EFEAFB !important;border-color:#7C5CC4 !important;color:#111 !important'],
    ['.war-memo-title.war-memo-title','color:#5B3FA6 !important'],
    ['a','color:#111 !important;text-decoration:none !important']
  ];
  (function(){
    const st=document.createElement('style');
    st.textContent='.war-print-bar{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin:0 0 14px}'
      +'.war-print-btn{cursor:pointer;font:inherit;font-weight:700;font-size:13.5px;padding:8px 16px;border-radius:999px;border:1px solid var(--accent);background:var(--card);color:var(--accent)}'
      +'.war-print-btn:hover{background:var(--accent);color:#fff}'
      +'.war-print-hint{font-size:12px;color:var(--ink-faint);line-height:1.6}'
      +'@media print{html body.war-printing{--paper:#fff;--card:#fff;--ink:#111;--ink-soft:#222;--ink-faint:#555;--line:#bbb;--gold:#B08A3C;--gold-soft:#F6EFDC;--ok:#1E7A4F;--ok-bg:#EAF6EF;--accent:#2E4A7A;--shadow:none;background:#fff !important;color:#111 !important}html body.war-printing *{visibility:visible !important;-webkit-print-color-adjust:exact;print-color-adjust:exact;box-shadow:none !important;animation:none !important}html body.war-printing>*:not(.wrap){display:none !important}'+PRINT_RULES.map(function(r){ return r[0].split(',').map(function(s){ return 'html body.war-printing '+s.trim(); }).join(',')+'{'+r[1]+'}'; }).join('')+'}';
    document.head.appendChild(st);
  })();
  const __printState=[];
  window.addEventListener('beforeprint',function(){
    __printState.length=0;
    if(!document.querySelector('#panel-waradmin.active,#panel-warconst.active')) return;
    document.body.classList.add('war-printing');
    if(!document.getElementById('war-page-style')){ const ps=document.createElement('style'); ps.id='war-page-style'; ps.textContent='@page{size:A4;margin:18mm 18mm 18mm 30mm}'; document.head.appendChild(ps); }
    document.querySelectorAll('.mode-panel.active details').forEach(d=>{ __printState.push([d,d.open]); d.open=true; });
  });
  window.addEventListener('afterprint',function(){
    document.body.classList.remove('war-printing');
    const ps=document.getElementById('war-page-style'); if(ps) ps.remove();
    __printState.forEach(x=>{ x[0].open=x[1]; }); __printState.length=0;
  });
  window.warPrint=function(){ window.print(); };
  const PRINT_BAR='<div class="war-print-bar"><button type="button" class="war-print-btn" onclick="warPrint()">🖨️ พิมพ์ / บันทึกเป็น PDF</button><span class="war-print-hint">พิมพ์ขนาด A4 เว้นขอบซ้าย 28 มม. สำหรับเจาะ/เย็บเล่ม (ขอบอื่น 14–18 มม.) · ขยายเฉลยและกล่อง "มาตราที่ต้องท่อง" ทุกข้ออัตโนมัติ · ในหน้าต่างพิมพ์เลือก Margins: Default และเปิด Background graphics เพื่อให้กล่องสีขึ้นครบ</span></div>';

  function memoHtml(list){
    if(!list||!list.length) return '';
    return '<div class="war-memo"><div class="war-memo-title">📌 มาตราที่ต้องท่อง</div><ul>'+list.map(x=>'<li>'+inl(x)+'</li>').join('')+'</ul></div>';
  }

  function lecQHtml(q){
    const facts=(q.facts||[]).map(p=>'<p>'+inl(p)+'</p>').join('');
    const asks=(q.asks||[]).map(p=>'<p class="war-ask">'+inl(p)+'</p>').join('');
    return '<div class="war-q" id="wl-'+q.id+'">'
      + '<div class="war-q-head"><span class="war-q-id">คาบ '+q.lec+' · ข้อ '+q.no+'</span><span class="war-q-kind">'+esc(q.kind)+'</span></div>'
      + '<div class="war-q-title">'+inl(q.title)+'</div>'
      + '<div class="war-q-body">'+facts+asks+'</div>'
      + '<details class="war-ans"><summary>👁 ดูเฉลยแบบตอบข้อสอบ + มาตราที่ต้องท่อง</summary>'
      + '<div class="exam-answer"><div class="ans-title">เฉลยแบบตอบข้อสอบ (ยึดตามที่บรรยายในคาบ · เพิ่มตัวบทประกอบให้อ่านรู้เรื่อง)</div>'+ansHtml(q.answer)+'</div>'
      + memoHtml(q.memo)
      + '</details></div>';
  }

  function lectureBankHtml(){
    const G=WAR_DATA.lecGroups, Q=WAR_DATA.lecQ;
    if(!G||!Q||!Q.length) return '';
    let inner='';
    G.forEach(g=>{
      const qs=Q.filter(q=>q.lec===g.lec);
      if(!qs.length) return;
      inner+='<details class="war-lec"><summary>'+esc(g.title)+'</summary><div class="war-lec-body">'+qs.map(lecQHtml).join('')+'<div class="war-note">อ่านเนื้อหาบรรยายที่เกี่ยวข้อง: <a href="#" onclick="warOpenLecture('+g.lec+');return false;">เปิดบรรยายครั้งที่ '+g.lec+'</a></div></div></details>';
    });
    if(!inner) return '';
    return '<details class="war-issue" id="war-issue-lec" open><summary><span class="war-issue-n">★</span><span class="war-issue-name">โจทย์ที่อาจารย์เฉลยในคาบ (ครั้งที่ 5–8) — 27 ข้อ</span><span class="war-issue-freq">เฉลยตามที่บรรยายจริง</span></summary>'
      + '<div class="war-issue-body"><div class="war-keys"><div class="war-keys-title">วิธีใช้</div><div>ชุดนี้คือโจทย์ตุ๊กตาที่อาจารย์เฉลยเองในคาบ เขียนเฉลยใหม่เป็นแบบตอบข้อสอบจริง (กึ่งบรรยาย ยกมาตราให้อ่านรู้เรื่อง วินิจฉัยตามข้อเท็จจริง สรุป และย่อหน้า "อนึ่ง") โดยยึดผลวินิจฉัยตามที่บรรยายในคาบ · ใต้เฉลยแต่ละข้อมี <b style="color:#7C5CC4">กล่องสีม่วง "มาตราที่ต้องท่อง"</b> รวมมาตราที่ควรจำให้ได้ · ลำดับการตอบ: เขตอำนาจมาตรา 9 → ผู้มีสิทธิฟ้องมาตรา 42 → อุทธรณ์ก่อนฟ้อง → ระยะเวลา → ค่าธรรมเนียม · หลายข้อซ้ำหรือใกล้เคียงกับโจทย์ในข้อสอบเก่าด้านบน · ชื่อตัวละครในโจทย์ปรับใหม่แล้ว</div></div>'+inner+'</div></details>';
  }

  window.warJump=function(ev,n){
    ev.preventDefault();
    const el=document.getElementById('war-issue-'+n);
    if(el){ el.open=true; el.scrollIntoView({behavior:'smooth',block:'start'}); }
  };
  window.warOpenLecture=function(n){
    switchMode('read');
    setTimeout(function(){ const r=document.getElementById('lec-'+n); if(r){ if(!r.classList.contains('open')) toggleLecture(n); r.scrollIntoView({behavior:'smooth',block:'start'}); } },50);
  };

  window.renderWarPanels=function(){
    const a=document.getElementById('panel-waradmin'), c=document.getElementById('panel-warconst');
    if(a) a.innerHTML=panelHtml('A');
    if(c) c.innerHTML=panelHtml('C');
  };
})();


